1	// Meeting-room booking server: JSON API, static page, one JSON data file.
2	// Node.js built-ins only.
3	import { createServer } from 'node:http';
4	import { readFile, writeFile } from 'node:fs/promises';
5	import { dirname, join, resolve } from 'node:path';
6	import { fileURLToPath } from 'node:url';
7	
8	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
9	const HOST = '127.0.0.1';
10	const DEFAULT_PORT = 3000;
11	const DEFAULT_DATA_FILE = 'bookings.json';
12	const MAX_BODY_BYTES = 10000;
13	const JSON_TYPE = 'application/json; charset=utf-8';
14	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
15	const BOOKINGS_PREFIX = '/api/bookings/';
16	const PUBLIC_DIR = join(dirname(fileURLToPath(import.meta.url)), 'public');
17	const STATIC_FILES = Object.freeze({
18	  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
19	  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8' },
20	});
21	
22	const MSG = Object.freeze({
23	  internal: 'internal error',
24	  notFound: 'not found',
25	  method: 'method not allowed',
26	  bookingNotFound: 'booking not found',
27	  contentType: 'content type must be application/json',
28	  tooLarge: 'body too large',
29	  notObject: 'body must be a JSON object',
30	  room: 'room must be one of Aurora, Borealis, Cosmos',
31	  title: 'title must be 1 to 80 characters',
32	  date: 'date must be a valid YYYY-MM-DD date',
33	  start: 'start must be HH:MM',
34	  end: 'end must be HH:MM',
35	  order: 'end must be after start',
36	});
37	
38	// ---------- validation helpers ----------
39	
40	const isPlainObject = (v) => typeof v === 'object' && v !== null && !Array.isArray(v);
41	
42	function isValidDate(value) {
43	  if (typeof value !== 'string' || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)) return false;
44	  const year = Number(value.slice(0, 4));
45	  const month = Number(value.slice(5, 7));
46	  const day = Number(value.slice(8, 10));
47	  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
48	  const daysInMonth = [31, year % 4 === 0 ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
49	  return day <= daysInMonth[month - 1];
50	}
51	
52	function isValidTime(value) {
53	  if (typeof value !== 'string' || !/^[0-9]{2}:[0-9]{2}$/.test(value)) return false;
54	  return Number(value.slice(0, 2)) <= 23 && Number(value.slice(3, 5)) <= 59;
55	}
56	
57	const isValidTitle = (t) => typeof t === 'string' && t.length >= 1 && t.length <= 80;
58	
59	const overlaps = (a, b) =>
60	  a.room === b.room && a.date === b.date && a.start < b.end && b.start < a.end;
61	
62	/** Returns an error message for the first failing field rule (4-9), or null. */
63	function fieldError(body) {
64	  if (typeof body.room !== 'string' || !ROOMS.includes(body.room)) return MSG.room;
65	  if (typeof body.title !== 'string' || !isValidTitle(body.title.trim())) return MSG.title;
66	  if (!isValidDate(body.date)) return MSG.date;
67	  if (!isValidTime(body.start)) return MSG.start;
68	  if (!isValidTime(body.end)) return MSG.end;
69	  if (body.end <= body.start) return MSG.order;
70	  return null;
71	}
72	
73	// ---------- data file ----------
74	
75	function isStoredBooking(b, nextId) {
76	  if (!isPlainObject(b)) return false;
77	  const keys = Object.keys(b);
78	  if (keys.length !== BOOKING_KEYS.length || !BOOKING_KEYS.every((k) => Object.hasOwn(b, k))) {
79	    return false;
80	  }
81	  if (!Number.isSafeInteger(b.id) || b.id < 1 || b.id >= nextId) return false;
82	  if (!ROOMS.includes(b.room) || !isValidDate(b.date)) return false;
83	  if (typeof b.title !== 'string' || b.title !== b.title.trim() || !isValidTitle(b.title)) {
84	    return false;
85	  }
86	  return isValidTime(b.start) && isValidTime(b.end) && b.start < b.end;
87	}
88	
89	/** Strict check that `data` is exactly what this server writes. */
90	function isValidStore(data) {
91	  if (!isPlainObject(data)) return false;
92	  const keys = Object.keys(data);
93	  if (keys.length !== 2 || !Object.hasOwn(data, 'nextId') || !Object.hasOwn(data, 'bookings')) {
94	    return false;
95	  }
96	  const { nextId, bookings } = data;
97	  if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return false;
98	  if (!bookings.every((b) => isStoredBooking(b, nextId))) return false;
99	  if (new Set(bookings.map((b) => b.id)).size !== bookings.length) return false;
100	  return bookings.every((b, i) => bookings.slice(i + 1).every((o) => !overlaps(b, o)));
101	}
102	
103	const emptyStore = () => Object.freeze({ nextId: 1, bookings: Object.freeze([]) });
104	
105	/** Resolves to the loaded store, or null when the file exists but is unusable. */
106	async function loadStore(path) {
107	  let text;
108	  try {
109	    text = await readFile(path, 'utf8');
110	  } catch (err) {
111	    if (err && err.code === 'ENOENT') return emptyStore();
112	    return null;
113	  }
114	  let data;
115	  try {
116	    data = JSON.parse(text);
117	  } catch {
118	    return null;
119	  }
120	  if (!isValidStore(data)) return null;
121	  return Object.freeze({
122	    nextId: data.nextId,
123	    bookings: Object.freeze(data.bookings.map((b) => Object.freeze({ ...b }))),
124	  });
125	}
126	
127	const saveStore = (path, store) => writeFile(path, JSON.stringify(store));
128	
129	// ---------- HTTP helpers ----------
130	
131	function sendJson(res, status, payload) {
132	  const body = JSON.stringify(payload);
133	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': Buffer.byteLength(body) });
134	  res.end(body);
135	}
136	
137	const sendError = (res, status, message) => sendJson(res, status, { error: message });
138	
139	function sendNoContent(res) {
140	  res.writeHead(204);
141	  res.end();
142	}
143	
144	/** Reads the whole body; keeps at most MAX_BODY_BYTES + 1 bytes, counts all of them. */
145	function readBody(req) {
146	  return new Promise((resolveBody, rejectBody) => {
147	    const chunks = [];
148	    let size = 0;
149	    let kept = 0;
150	    req.on('data', (chunk) => {
151	      size += chunk.length;
152	      if (kept <= MAX_BODY_BYTES) {
153	        chunks.push(chunk);
154	        kept += chunk.length;
155	      }
156	    });
157	    req.on('end', () => resolveBody({ size, buffer: Buffer.concat(chunks) }));
158	    req.on('error', rejectBody);
159	    req.on('close', () => {
160	      if (!req.complete) rejectBody(new Error('request closed before its body was read'));
161	    });
162	  });
163	}
164	
165	function mediaType(header) {
166	  if (typeof header !== 'string') return null;
167	  return header
168	    .split(';')[0]
169	    .replace(/^[ \t]+|[ \t]+$/g, '')
170	    .replace(/[A-Z]/g, (c) => c.toLowerCase());
171	}
172	
173	function parseObject(buffer) {
174	  try {
175	    const value = JSON.parse(buffer.toString('utf8'));
176	    return isPlainObject(value) ? value : null;
177	  } catch {
178	    return null;
179	  }
180	}
181	
182	function compareBookings(a, b) {
183	  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
184	  if (a.start !== b.start) return a.start < b.start ? -1 : 1;
185	  const byRoom = ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room);
186	  return byRoom !== 0 ? byRoom : a.id - b.id;
187	}
188	
189	// ---------- application ----------
190	
191	function createApp(dataPath, initialStore) {
192	  let store = initialStore;
193	  let queue = Promise.resolve();
194	
195	  // Runs mutations one at a time. The returned promise carries the task's own
196	  // result or error to the caller; the chain itself only needs to keep going.
197	  function serialize(task) {
198	    const run = queue.then(task);
199	    queue = run.then(
200	      () => undefined,
201	      () => undefined,
202	    );
203	    return run;
204	  }
205	
206	  async function commit(next) {
207	    await saveStore(dataPath, next);
208	    store = next;
209	  }
210	
211	  function listBookings(res, query) {
212	    const params = new URLSearchParams(query);
213	    let bookings = store.bookings;
214	    if (params.has('date')) {
215	      const date = params.get('date');
216	      if (!isValidDate(date)) return sendError(res, 400, MSG.date);
217	      bookings = bookings.filter((b) => b.date === date);
218	    }
219	    return sendJson(res, 200, { bookings: [...bookings].sort(compareBookings) });
220	  }
221	
222	  async function createBooking(req, res, body) {
223	    if (mediaType(req.headers['content-type']) !== 'application/json') {
224	      return sendError(res, 415, MSG.contentType);
225	    }
226	    if (body.size > MAX_BODY_BYTES) return sendError(res, 413, MSG.tooLarge);
227	    const input = parseObject(body.buffer);
228	    if (input === null) return sendError(res, 400, MSG.notObject);
229	    const invalid = fieldError(input);
230	    if (invalid !== null) return sendError(res, 400, invalid);
231	    const fields = {
232	      room: input.room,
233	      title: input.title.trim(),
234	      date: input.date,
235	      start: input.start,
236	      end: input.end,
237	    };
238	    return serialize(async () => {
239	      const clash = store.bookings
240	        .filter((b) => overlaps(b, fields))
241	        .sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0))[0];
242	      if (clash) {
243	        return sendError(res, 409, `room is already booked from ${clash.start} to ${clash.end}`);
244	      }
245	      const booking = Object.freeze({ id: store.nextId, ...fields });
246	      await commit(
247	        Object.freeze({
248	          nextId: store.nextId + 1,
249	          bookings: Object.freeze([...store.bookings, booking]),
250	        }),
251	      );
252	      return sendJson(res, 201, booking);
253	    });
254	  }
255	
256	  function deleteBooking(res, idText) {
257	    return serialize(async () => {
258	      const found =
259	        /^[1-9][0-9]*$/.test(idText) && store.bookings.some((b) => String(b.id) === idText);
260	      if (!found) return sendError(res, 404, MSG.bookingNotFound);
261	      await commit(
262	        Object.freeze({
263	          nextId: store.nextId,
264	          bookings: Object.freeze(store.bookings.filter((b) => String(b.id) !== idText)),
265	        }),
266	      );
267	      return sendNoContent(res);
268	    });
269	  }
270	
271	  async function serveStatic(res, entry) {
272	    const content = await readFile(join(PUBLIC_DIR, entry.file));
273	    res.writeHead(200, { 'Content-Type': entry.type, 'Content-Length': content.length });
274	    res.end(content);
275	  }
276	
277	  async function route(req, res, body) {
278	    const target = req.url ?? '';
279	    const qIndex = target.indexOf('?');
280	    const path = qIndex === -1 ? target : target.slice(0, qIndex);
281	    const query = qIndex === -1 ? '' : target.slice(qIndex + 1);
282	    const method = req.method;
283	
284	    if (path === '/api/rooms') {
285	      return method === 'GET' ? sendJson(res, 200, { rooms: [...ROOMS] }) : sendError(res, 405, MSG.method);
286	    }
287	    if (path === '/api/bookings') {
288	      if (method === 'GET') return listBookings(res, query);
289	      if (method === 'POST') return createBooking(req, res, body);
290	      return sendError(res, 405, MSG.method);
291	    }
292	    if (path.startsWith(BOOKINGS_PREFIX)) {
293	      const idText = path.slice(BOOKINGS_PREFIX.length);
294	      if (idText === '' || idText.includes('/')) return sendError(res, 404, MSG.notFound);
295	      return method === 'DELETE' ? deleteBooking(res, idText) : sendError(res, 405, MSG.method);
296	    }
297	    if (Object.hasOwn(STATIC_FILES, path)) {
298	      return method === 'GET' ? serveStatic(res, STATIC_FILES[path]) : sendError(res, 405, MSG.method);
299	    }
300	    return sendError(res, 404, MSG.notFound);
301	  }
302	
303	  function replyInternalError(res) {
304	    if (res.headersSent) {
305	      res.destroy();
306	      return;
307	    }
308	    sendError(res, 500, MSG.internal);
309	  }
310	
311	  return async function handle(req, res) {
312	    try {
313	      const body = await readBody(req);
314	      await route(req, res, body);
315	    } catch {
316	      // Any unexpected failure (save error, unreadable page, broken request)
317	      // becomes a generic 500; details are never sent to the client.
318	      replyInternalError(res);
319	    }
320	  };
321	}
322	
323	// ---------- startup ----------
324	
325	function fail(line) {
326	  process.stderr.write(`${line}\n`, () => process.exit(1));
327	}
328	
329	function parsePort(raw) {
330	  if (raw === undefined || raw === '') return DEFAULT_PORT;
331	  if (!/^[0-9]+$/.test(raw)) return null;
332	  const port = Number(raw);
333	  return port <= 65535 ? port : null;
334	}
335	
336	async function main() {
337	  const port = parsePort(process.env.PORT);
338	  if (port === null) return fail(`invalid PORT: ${process.env.PORT}`);
339	
340	  const dataName = process.env.DATA_FILE || DEFAULT_DATA_FILE;
341	  const dataPath = resolve(process.cwd(), dataName);
342	  const store = await loadStore(dataPath);
343	  if (store === null) return fail(`cannot read data file ${dataName}`);
344	
345	  const handle = createApp(dataPath, store);
346	  const server = createServer((req, res) => {
347	    handle(req, res).catch(() => res.destroy());
348	  });
349	  server.once('error', (err) => fail(`cannot listen on ${HOST}:${port}: ${err.code ?? 'error'}`));
350	  server.listen(port, HOST, () => {
351	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
352	  });
353	  return undefined;
354	}
355	
356	main().catch(() => fail('server failed to start'));
